// Real Google Map for the map view — NOT generated by Figma Make, safe from re-exports.
import { Component, useEffect, useRef, useState, type ReactNode } from "react";
import {
  APIProvider,
  AdvancedMarker,
  AdvancedMarkerAnchorPoint,
  APILoadingStatus,
  Map,
  useApiLoadingStatus,
  useMap,
} from "@vis.gl/react-google-maps";
import { searchNearbySpots, type LatLng, type PlaceSpot } from "../lib/places";
import "./StudyMap.css";

const API_KEY: string = import.meta.env.VITE_GOOGLE_MAPS_API_KEY ?? "";
export const hasGoogleMapsKey = API_KEY.trim().length > 0;

/** University of Washington, Seattle — used when geolocation is unavailable/denied. */
export const DEFAULT_CENTER: LatLng = { lat: 47.6553, lng: -122.3035 };

type MinimalSpot = Pick<PlaceSpot, "id" | "name" | "position"> & { location?: LatLng };

type StudyMapProps<S extends MinimalSpot> = {
  spots: S[];
  selectedId: number;
  onSelect: (id: number) => void;
  /** Renders the pin for a spot (App passes its existing <Stamp/>). */
  renderPin: (spot: S) => ReactNode;
  /** Called with Places results once they load. */
  onPlacesLoaded?: (spots: PlaceSpot[]) => void;
  /** Called when we fall back to the hand-drawn map (no key / auth failure). */
  onFallback?: () => void;
  /** The original hand-drawn map, shown when Google Maps can't be used. */
  fallback: ReactNode;
};

/** Sample spots have only % positions; scatter them around the center so they still show. */
function spotLocation(spot: MinimalSpot, center: LatLng): LatLng {
  if (spot.location) return spot.location;
  const left = parseFloat(spot.position.left) / 100 || 0.5;
  const top = parseFloat(spot.position.top) / 100 || 0.5;
  return { lat: center.lat + (0.5 - top) * 0.014, lng: center.lng + (left - 0.5) * 0.02 };
}

export default function StudyMap<S extends MinimalSpot>(props: StudyMapProps<S>) {
  if (!hasGoogleMapsKey) {
    return (
      <>
        {props.fallback}
        <p className="study-map-notice">Add a Google Maps key to see the real map — showing sample spots.</p>
      </>
    );
  }
  return (
    <MapErrorBoundary fallback={props.fallback} onError={props.onFallback}>
      <APIProvider apiKey={API_KEY}>
        <StudyMapInner {...props} />
      </APIProvider>
    </MapErrorBoundary>
  );
}

/** If Google Maps throws (bad key, blocked script…), show the hand-drawn map instead of a blank app. */
class MapErrorBoundary extends Component<
  { fallback: ReactNode; onError?: () => void; children: ReactNode },
  { failed: boolean }
> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  componentDidCatch(error: unknown) {
    console.warn("[StudyMap] Google Maps crashed, using fallback map:", error);
    this.props.onError?.();
  }
  render() {
    if (!this.state.failed) return this.props.children;
    return (
      <>
        {this.props.fallback}
        <p className="study-map-notice">Google Maps couldn't load — showing sample spots.</p>
      </>
    );
  }
}

function StudyMapInner<S extends MinimalSpot>({
  spots,
  selectedId,
  onSelect,
  renderPin,
  onPlacesLoaded,
  onFallback,
  fallback,
}: StudyMapProps<S>) {
  const status = useApiLoadingStatus();
  const [center, setCenter] = useState<LatLng | null>(null);
  const [userLocation, setUserLocation] = useState<LatLng | null>(null);
  const [notice, setNotice] = useState("Finding you…");
  const searched = useRef(false);
  const failed = status === APILoadingStatus.AUTH_FAILURE || status === APILoadingStatus.FAILED;

  // 1. Locate the user (falls back to UW).
  useEffect(() => {
    if (!("geolocation" in navigator)) {
      setCenter(DEFAULT_CENTER);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      ({ coords }) => {
        const here = { lat: coords.latitude, lng: coords.longitude };
        setUserLocation(here);
        setCenter(here);
      },
      () => {
        setCenter(DEFAULT_CENTER);
        setNotice("Location off — showing spots near UW.");
      },
      { enableHighAccuracy: false, timeout: 8000, maximumAge: 5 * 60 * 1000 },
    );
  }, []);

  // 2. Once the API is loaded and we know where we are, search nearby (once).
  useEffect(() => {
    if (status !== APILoadingStatus.LOADED || !center || searched.current) return;
    searched.current = true;
    setNotice((current) => (current.startsWith("Location off") ? current : "Looking for nearby nooks…"));
    searchNearbySpots(center)
      .then((results) => {
        if (results.length) {
          onPlacesLoaded?.(results);
          setNotice("");
        } else {
          setNotice("No cafes or libraries nearby — showing sample spots.");
        }
      })
      .catch((error) => {
        console.warn("[StudyMap] Places nearby search failed:", error);
        setNotice("Couldn't reach Google Places — showing sample spots.");
      });
  }, [status, center, onPlacesLoaded]);

  useEffect(() => {
    if (failed) onFallback?.();
  }, [failed, onFallback]);

  const base = center ?? DEFAULT_CENTER;
  return (
    <>
    {/* On failure keep the Google map mounted (unmounting it after an auth error throws) but hide it. */}
    <div className={`study-map ${failed ? "study-map--failed" : ""}`}>
      <Map
        mapId="DEMO_MAP_ID"
        defaultCenter={DEFAULT_CENTER}
        defaultZoom={15}
        gestureHandling="greedy"
        disableDefaultUI
        clickableIcons={false}
      >
        <Recenter center={center} />
        {spots.map((spot) => (
          <AdvancedMarker
            key={spot.id}
            position={spotLocation(spot, base)}
            anchorPoint={AdvancedMarkerAnchorPoint.CENTER}
            zIndex={spot.id === selectedId ? 10 : 1}
            title={spot.name}
            onClick={() => onSelect(spot.id)}
          >
            <div className="study-map-pin">{renderPin(spot)}</div>
          </AdvancedMarker>
        ))}
        {userLocation && (
          <AdvancedMarker position={userLocation} anchorPoint={AdvancedMarkerAnchorPoint.CENTER} zIndex={0}>
            <div className="you-are-here study-map-you"><span /> YOU ARE HERE</div>
          </AdvancedMarker>
        )}
        <Controls home={userLocation ?? base} />
      </Map>
      {!failed && notice && <p className="study-map-notice">{notice}</p>}
      {!failed && spots.length === 0 && <p className="no-results">No stamps here yet.</p>}
    </div>
    {failed && (
      <>
        {fallback}
        <p className="study-map-notice">Google Maps couldn't load (check the API key) — showing sample spots.</p>
      </>
    )}
    </>
  );
}

function Recenter({ center }: { center: LatLng | null }) {
  const map = useMap();
  useEffect(() => {
    if (map && center) map.panTo(center);
  }, [map, center]);
  return null;
}

/** Same markup/classes as the original hand-drawn map controls. */
function Controls({ home }: { home: LatLng }) {
  const map = useMap();
  const zoom = (amount: number) => map?.setZoom((map.getZoom() ?? 15) + amount);
  return (
    <div className="map-controls" aria-label="Map controls">
      <button onClick={() => zoom(1)} aria-label="Zoom in">+</button>
      <button onClick={() => zoom(-1)} aria-label="Zoom out">−</button>
      <button
        className="recenter-map"
        onClick={() => {
          map?.panTo(home);
          map?.setZoom(15);
        }}
        aria-label="Recenter map"
      >
        ◎
      </button>
    </div>
  );
}
